package com.company.platform.integration.infrastructure;import java.util.*;import org.apache.kafka.clients.consumer.ConsumerConfig;import org.apache.kafka.common.serialization.StringDeserializer;import org.apache.kafka.clients.producer.ProducerConfig;import org.apache.kafka.common.serialization.StringSerializer;import org.springframework.context.annotation.*;import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;import org.springframework.kafka.core.*;import org.springframework.kafka.listener.DefaultErrorHandler;import org.springframework.util.backoff.FixedBackOff;
@Configuration public class KafkaConfiguration{@Bean ConsumerFactory<String,String> consumerFactory(){Map<String,Object>p=new HashMap<>();p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG,System.getenv().getOrDefault("KAFKA_BOOTSTRAP_SERVERS","localhost:9092"));p.put(ConsumerConfig.GROUP_ID_CONFIG,"integration-service");p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG,StringDeserializer.class);p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,StringDeserializer.class);return new DefaultKafkaConsumerFactory<>(p);}@Bean ConcurrentKafkaListenerContainerFactory<String,String> kafkaListenerContainerFactory(ConsumerFactory<String,String>f,KafkaTemplate<String,String>template){var x=new ConcurrentKafkaListenerContainerFactory<String,String>();x.setConsumerFactory(f);x.setCommonErrorHandler(new DefaultErrorHandler(new org.springframework.kafka.listener.DeadLetterPublishingRecoverer(template),new FixedBackOff(1000,3)));return x;}@Bean ProducerFactory<String,String> producerFactory(){Map<String,Object>p=new HashMap<>();p.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG,System.getenv().getOrDefault("KAFKA_BOOTSTRAP_SERVERS","localhost:9092"));p.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG,StringSerializer.class);p.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,StringSerializer.class);return new DefaultKafkaProducerFactory<>(p);}@Bean KafkaTemplate<String,String> kafkaTemplate(ProducerFactory<String,String>f){return new KafkaTemplate<>(f);}}
